SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP VIEW IF EXISTS v_admin_kpis;
DROP VIEW IF EXISTS v_category_stats;
DROP VIEW IF EXISTS v_item_current_custody;
DROP VIEW IF EXISTS v_item_overview;
DROP VIEW IF EXISTS v_item_timeline;
DROP VIEW IF EXISTS v_open_fraud_flags;
DROP VIEW IF EXISTS v_staff_workload;
DROP VIEW IF EXISTS v_unclaimed_by_location;

CREATE VIEW `v_admin_kpis` AS select (select count(0) from `items`) AS `total_items`,(select count(0) from `items` where `items`.`status` = 'RETURNED') AS `returned_items`,(select count(0) from `items` where `items`.`status` in ('REGISTERED','CLAIMED')) AS `open_items`,round(100.0 * (select count(0) from `items` where `items`.`status` = 'RETURNED') / nullif((select count(0) from `items`),0),1) AS `return_rate_pct`,(select round(avg(timestampdiff(MINUTE,`items`.`found_at`,`items`.`returned_at`)) / 60.0,1) from `items` where `items`.`status` = 'RETURNED') AS `avg_hours_to_return`,(select count(0) from `items` where `items`.`status` = 'REGISTERED' and `items`.`registered_at` < current_timestamp() - interval 14 day) AS `unclaimed_over_14d`,(select count(0) from `claims` where `claims`.`status` = 'PENDING') AS `pending_claims`,(select count(0) from `fraud_flags` where `fraud_flags`.`status` = 'OPEN') AS `open_fraud_flags`,(select count(0) from `users`) AS `total_users`;

CREATE VIEW `v_category_stats` AS select `c`.`category_id` AS `category_id`,`c`.`name` AS `category`,count(`i`.`item_id`) AS `total_items`,sum(`i`.`status` = 'RETURNED') AS `returned_items`,round(100.0 * sum(`i`.`status` = 'RETURNED') / nullif(count(`i`.`item_id`),0),1) AS `return_rate_pct`,round(avg(case when `i`.`status` = 'RETURNED' then timestampdiff(MINUTE,`i`.`found_at`,`i`.`returned_at`) / 60.0 end),1) AS `avg_hours_to_return` from (`categories` `c` left join `items` `i` on(`i`.`category_id` = `c`.`category_id`)) group by `c`.`category_id`,`c`.`name`;

CREATE VIEW `v_item_current_custody` AS select `c`.`item_id` AS `item_id`,`c`.`holder_id` AS `holder_id`,`u`.`full_name` AS `holder_name`,`u`.`role` AS `holder_role`,`c`.`started_at` AS `held_since`,`c`.`storage_place` AS `storage_place` from (`custody_log` `c` join `users` `u` on(`u`.`user_id` = `c`.`holder_id`)) where `c`.`ended_at` is null;

CREATE VIEW `v_item_overview` AS select `i`.`item_id` AS `item_id`,`i`.`title` AS `title`,`i`.`description` AS `description`,`i`.`color` AS `color`,`i`.`brand` AS `brand`,`i`.`status` AS `status`,`i`.`found_at` AS `found_at`,`i`.`registered_at` AS `registered_at`,`i`.`returned_at` AS `returned_at`,`i`.`verification_hint` AS `verification_hint`,`i`.`verification_hint` is not null AS `has_hidden_detail`,`cat`.`category_id` AS `category_id`,`cat`.`name` AS `category`,`loc`.`location_id` AS `location_id`,`loc`.`name` AS `location_name`,`loc`.`location_type` AS `location_type`,`loc`.`city` AS `city`,`i`.`finder_id` AS `finder_id`,`f`.`full_name` AS `finder_name`,`cu`.`holder_id` AS `holder_id`,`cu`.`holder_name` AS `holder_name`,`cu`.`storage_place` AS `storage_place`,(select count(0) from `claims` `cl` where `cl`.`item_id` = `i`.`item_id` and `cl`.`status` in ('PENDING','VERIFIED','FULFILLED')) AS `active_claims`,to_days(current_timestamp()) - to_days(`i`.`found_at`) AS `days_since_found` from ((((`items` `i` join `categories` `cat` on(`cat`.`category_id` = `i`.`category_id`)) join `locations` `loc` on(`loc`.`location_id` = `i`.`found_location_id`)) join `users` `f` on(`f`.`user_id` = `i`.`finder_id`)) left join `v_item_current_custody` `cu` on(`cu`.`item_id` = `i`.`item_id`));

CREATE VIEW `v_item_timeline` AS select `i`.`item_id` AS `item_id`,`i`.`created_at` AS `event_time`,'REPORTED' AS `event_type`,`u`.`full_name` AS `actor`,concat('Reported found: ',`i`.`title`) AS `detail` from (`items` `i` join `users` `u` on(`u`.`user_id` = `i`.`finder_id`)) union all select `c`.`item_id` AS `item_id`,`c`.`started_at` AS `started_at`,'CUSTODY' AS `CUSTODY`,`h`.`full_name` AS `full_name`,concat('Took custody',if(`c`.`from_user_id` is null,'',concat(' from ',`fu`.`full_name`)),if(`c`.`storage_place` is null,'',concat(' - stored at ',`c`.`storage_place`))) AS `Name_exp_5` from ((`custody_log` `c` join `users` `h` on(`h`.`user_id` = `c`.`holder_id`)) left join `users` `fu` on(`fu`.`user_id` = `c`.`from_user_id`)) union all select `cl`.`item_id` AS `item_id`,`cl`.`submitted_at` AS `submitted_at`,'CLAIM_SUBMITTED' AS `CLAIM_SUBMITTED`,`u`.`full_name` AS `full_name`,concat('Claim #',`cl`.`claim_id`,' submitted') AS `CONCAT('Claim #', cl.claim_id, ' submitted')` from (`claims` `cl` join `users` `u` on(`u`.`user_id` = `cl`.`claimant_id`)) union all select `cl`.`item_id` AS `item_id`,`va`.`attempted_at` AS `attempted_at`,'VERIFICATION' AS `VERIFICATION`,`s`.`full_name` AS `full_name`,concat('Claim #',`cl`.`claim_id`,' ',`va`.`method`,' check: ',`va`.`outcome`) AS `Name_exp_5` from ((`verification_attempts` `va` join `claims` `cl` on(`cl`.`claim_id` = `va`.`claim_id`)) join `users` `s` on(`s`.`user_id` = `va`.`staff_id`)) union all select `ho`.`item_id` AS `item_id`,`ho`.`handed_at` AS `handed_at`,'HANDOVER' AS `HANDOVER`,`g`.`full_name` AS `full_name`,concat(`ho`.`handover_type`,': ',`g`.`full_name`,' -> ',`r`.`full_name`,' (proof: ',`ho`.`proof_type`,' ',`ho`.`proof_reference`,')') AS `Name_exp_5` from ((`handovers` `ho` join `users` `g` on(`g`.`user_id` = `ho`.`from_user_id`)) join `users` `r` on(`r`.`user_id` = `ho`.`to_user_id`)) union all select `i`.`item_id` AS `item_id`,`i`.`returned_at` AS `returned_at`,'RETURNED' AS `RETURNED`,`o`.`full_name` AS `full_name`,'Owner confirmed receipt - case closed' AS `Owner confirmed receipt - case closed` from ((`items` `i` join `claims` `cl` on(`cl`.`item_id` = `i`.`item_id` and `cl`.`status` = 'FULFILLED')) join `users` `o` on(`o`.`user_id` = `cl`.`claimant_id`)) where `i`.`returned_at` is not null;

CREATE VIEW `v_open_fraud_flags` AS select `ff`.`flag_id` AS `flag_id`,`ff`.`reason` AS `reason`,`ff`.`severity` AS `severity`,`ff`.`status` AS `status`,`ff`.`details` AS `details`,`ff`.`created_at` AS `created_at`,`ff`.`user_id` AS `user_id`,`u`.`full_name` AS `user_name`,`u`.`email` AS `user_email`,`ff`.`item_id` AS `item_id`,`i`.`title` AS `item_title`,`ff`.`claim_id` AS `claim_id` from ((`fraud_flags` `ff` join `users` `u` on(`u`.`user_id` = `ff`.`user_id`)) left join `items` `i` on(`i`.`item_id` = `ff`.`item_id`)) where `ff`.`status` = 'OPEN';

CREATE VIEW `v_staff_workload` AS select `u`.`user_id` AS `user_id`,`u`.`full_name` AS `full_name`,`u`.`role` AS `role`,(select count(0) from (`custody_log` `c` join `items` `i` on(`i`.`item_id` = `c`.`item_id`)) where `c`.`holder_id` = `u`.`user_id` and `c`.`ended_at` is null and `i`.`status` in ('REGISTERED','CLAIMED','VERIFIED')) AS `items_in_custody`,(select count(0) from `handovers` `h` where `h`.`from_user_id` = `u`.`user_id` and `h`.`handover_type` = 'STAFF_TO_OWNER') AS `handovers_completed`,(select count(0) from `verification_attempts` `va` where `va`.`staff_id` = `u`.`user_id`) AS `verifications_done` from `users` `u` where `u`.`role` in ('staff','admin') and `u`.`is_active` = 1;

CREATE VIEW `v_unclaimed_by_location` AS select `l`.`location_id` AS `location_id`,`l`.`name` AS `location_name`,`l`.`location_type` AS `location_type`,`l`.`city` AS `city`,count(0) AS `unclaimed_items`,min(`i`.`found_at`) AS `oldest_found_at`,round(avg(to_days(current_timestamp()) - to_days(`i`.`found_at`)),1) AS `avg_age_days` from (`items` `i` join `locations` `l` on(`l`.`location_id` = `i`.`found_location_id`)) where `i`.`status` = 'REGISTERED' group by `l`.`location_id`,`l`.`name`,`l`.`location_type`,`l`.`city` having count(0) >= 1;

